#!/usr/bin/env python3
"""
Unified Product Category Taxonomy Builder

This script processes category files from Amazon, Facebook, and Google Shopping
and creates a unified 5-level taxonomy.
"""

import csv
import re
from collections import defaultdict, Counter
from typing import Dict, List, Tuple, Set, Optional
import os

# Configuration
INPUT_DIR = "/root/data"
OUTPUT_DIR = "/root/output"

# File paths
FILES = {
    "amazon": os.path.join(INPUT_DIR, "amazon_product_categories.csv"),
    "facebook": os.path.join(INPUT_DIR, "fb_product_categories.csv"),
    "google": os.path.join(INPUT_DIR, "google_shopping_product_categories.csv"),
}


def normalize_text(text: str) -> str:
    """Normalize category text: lowercase, strip, standardize spaces."""
    text = text.strip().lower()
    # Remove quotes
    text = text.strip('"').strip("'")
    # Standardize multiple spaces
    text = re.sub(r'\s+', ' ', text)
    return text.strip()


def title_case(text: str) -> str:
    """Convert to title case, preserving & and common abbreviations."""
    words = text.split()
    result = []
    abbrevs = {'tv', 'dvd', 'cd', 'pc', 'usb', 'led', 'lcd', 'hd', 'gps', 'mp3', 'atv', 'diy', 'rc', 'ac', 'dc'}
    for word in words:
        if word.lower() in abbrevs:
            result.append(word.upper())
        elif word == '&':
            result.append('&')
        elif word == '|':
            result.append('|')
        else:
            result.append(word.capitalize())
    return ' '.join(result)


def parse_category_path(path: str) -> List[str]:
    """Parse a category path into list of levels."""
    # Handle different separators
    if ' > ' in path:
        parts = path.split(' > ')
    elif '>' in path:
        parts = path.split('>')
    else:
        parts = [path]

    return [normalize_text(p) for p in parts if p.strip()]


def load_categories() -> Dict[str, List[Tuple[str, List[str]]]]:
    """Load categories from all sources."""
    categories = {
        "amazon": [],
        "facebook": [],
        "google": []
    }

    # Load Amazon
    with open(FILES["amazon"], 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            path = row.get('category_path', '')
            if path:
                parsed = parse_category_path(path)
                if parsed:
                    categories["amazon"].append((path, parsed))

    # Load Facebook
    with open(FILES["facebook"], 'r', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        for row in reader:
            path = row.get('category_path', '')
            if path:
                parsed = parse_category_path(path)
                if parsed:
                    categories["facebook"].append((path, parsed))

    # Load Google
    with open(FILES["google"], 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            path = row.get('category_path', '')
            if path:
                parsed = parse_category_path(path)
                if parsed:
                    categories["google"].append((path, parsed))

    print(f"Loaded categories: Amazon={len(categories['amazon'])}, Facebook={len(categories['facebook'])}, Google={len(categories['google'])}")
    return categories


def get_word_set(text: str) -> Set[str]:
    """Get set of significant words from text."""
    words = re.findall(r'\b\w+\b', text.lower())
    # Filter out common words
    stopwords = {'and', 'or', 'the', 'a', 'an', 'of', 'for', 'in', 'on', 'to', 'with', 'by', 'products', 'supplies', 'accessories', 'equipment', 'items', 'other', 'general'}
    return {w for w in words if len(w) > 1 and w not in stopwords}


def word_overlap_ratio(text1: str, text2: str) -> float:
    """Calculate word overlap ratio between two texts."""
    words1 = get_word_set(text1)
    words2 = get_word_set(text2)
    if not words1 or not words2:
        return 0.0
    intersection = words1 & words2
    return len(intersection) / min(len(words1), len(words2))


# Define top-level category mappings
TOP_LEVEL_CATEGORIES = [
    ("Electronics | Technology", [
        "electronics", "computers", "camera", "photo", "phone", "mobile", "video games",
        "software", "tv", "audio", "smart home", "wearable", "tablet", "laptop",
        "headphone", "speaker", "monitor", "printer", "network", "gaming"
    ]),
    ("Clothing | Fashion | Apparel", [
        "clothing", "shoes", "jewelry", "fashion", "apparel", "accessories", "watches",
        "luggage", "bags", "handbag", "wallet", "sunglasses", "belt", "tie", "scarf",
        "hat", "gloves", "uniform", "costume", "dress", "shirt", "pants", "jeans"
    ]),
    ("Home | Garden | Living", [
        "home", "kitchen", "garden", "patio", "lawn", "furniture", "bedding", "bath",
        "home improvement", "decor", "lighting", "storage", "cleaning", "laundry",
        "housekeeping", "pool", "outdoor living", "heating", "cooling", "hvac"
    ]),
    ("Health | Beauty | Personal Care", [
        "health", "beauty", "personal care", "vitamins", "skin care", "hair care",
        "cosmetics", "makeup", "fragrance", "wellness", "medical", "pharmacy",
        "oral care", "shaving", "grooming", "massage", "spa", "nutrition"
    ]),
    ("Sports | Outdoors | Fitness", [
        "sports", "outdoors", "fitness", "exercise", "outdoor recreation", "camping",
        "cycling", "sporting goods", "hunting", "fishing", "hiking", "gym", "yoga",
        "running", "swimming", "golf", "tennis", "basketball", "soccer", "football"
    ]),
    ("Toys | Games | Hobbies", [
        "toys", "games", "hobbies", "puzzles", "dolls", "action figures", "board games",
        "video game", "collectibles", "model", "rc", "lego", "playsets", "stuffed"
    ]),
    ("Baby | Kids | Nursery", [
        "baby", "kids", "nursery", "children", "toddler", "infant", "maternity",
        "stroller", "car seat", "diaper", "feeding", "bathing"
    ]),
    ("Pet Supplies | Animals", [
        "pet", "animals", "dog", "cat", "bird", "fish", "reptile", "horse",
        "aquarium", "terrarium", "small animal", "veterinary"
    ]),
    ("Food | Grocery | Beverages", [
        "food", "grocery", "beverages", "gourmet", "snacks", "drinks", "coffee", "tea",
        "wine", "beer", "alcohol", "organic", "pantry", "frozen", "dairy", "meat",
        "seafood", "bakery", "produce"
    ]),
    ("Automotive | Vehicles | Parts", [
        "automotive", "car", "motorcycle", "vehicle", "truck", "auto parts", "tires",
        "wheels", "engine", "battery", "oil", "brake", "powersports", "atv", "boat"
    ]),
    ("Books | Media | Entertainment", [
        "books", "movies", "music", "cds", "dvd", "vinyl", "magazine", "newspaper",
        "audiobook", "ebook", "kindle", "literature", "fiction", "nonfiction"
    ]),
    ("Office | Business | Industrial", [
        "office", "business", "industrial", "scientific", "school", "stationery",
        "lab", "manufacturing", "commercial", "professional", "janitorial"
    ]),
    ("Arts | Crafts | Sewing", [
        "arts", "crafts", "sewing", "painting", "drawing", "knitting", "quilting",
        "scrapbooking", "beading", "fabric", "yarn", "needlework"
    ]),
    ("Hardware | Tools | Equipment", [
        "hardware", "tools", "power tools", "hand tools", "building", "construction",
        "plumbing", "electrical", "welding", "safety", "measuring"
    ]),
    ("Religious | Spiritual | Occasions", [
        "religious", "spiritual", "wedding", "party", "occasion", "holiday", "gift",
        "celebration", "memorial", "funeral", "ceremony"
    ]),
    ("Services | Software | Digital", [
        "services", "software", "digital", "subscription", "membership", "warranty",
        "installation", "consulting", "training", "support"
    ]),
]


def determine_top_level(parsed_path: List[str]) -> str:
    """Determine the top-level unified category for a path."""
    # Check first 2 levels for matching keywords
    text_to_check = ' '.join(parsed_path[:2]).lower()

    best_match = None
    best_score = 0

    for category_name, keywords in TOP_LEVEL_CATEGORIES:
        score = 0
        for keyword in keywords:
            if keyword in text_to_check:
                # Longer keyword matches get higher scores
                score += len(keyword.split())
        if score > best_score:
            best_score = score
            best_match = category_name

    return best_match if best_match else "Other | Miscellaneous"


def create_unified_name(names: List[str], parent_name: str = "", max_words: int = 3) -> str:
    """Create a unified category name from multiple names."""
    if not names:
        return "General"

    # Count word frequencies
    word_freq = Counter()
    for name in names:
        words = get_word_set(name)
        word_freq.update(words)

    # Get parent words to avoid overlap
    parent_words = get_word_set(parent_name) if parent_name else set()

    # Get most common words not in parent
    selected = []
    total_names = len(names)

    for word, count in word_freq.most_common():
        if word not in parent_words and len(word) > 2:
            # Check representativeness (at least 30% of names or common enough)
            coverage = count / total_names
            if coverage >= 0.3 or count >= max(3, total_names * 0.2):
                selected.append(word)
                if len(selected) >= max_words:
                    break

    if not selected:
        # Fallback: use most frequent word from first name
        first_words = get_word_set(names[0])
        if first_words:
            selected = [list(first_words)[0]]
        else:
            # Use first name directly
            clean_name = re.sub(r'[^\w\s]', '', names[0])[:20]
            return title_case(clean_name)

    return " | ".join(title_case(w) for w in selected)


def cluster_similar_names(names: List[str], max_clusters: int = 20, min_cluster_size: int = 1) -> Dict[str, List[str]]:
    """Cluster similar names together based on word similarity."""
    if not names:
        return {}

    if len(names) <= max_clusters:
        return {name: [name] for name in names}

    # Group by primary keyword
    clusters = defaultdict(list)
    unmatched = []

    # Define keyword priorities for clustering
    keyword_priority = [
        'accessories', 'clothing', 'shoes', 'jewelry', 'electronics', 'food',
        'toys', 'games', 'sports', 'home', 'beauty', 'health', 'office',
        'automotive', 'books', 'pet', 'baby', 'tools', 'garden', 'kitchen'
    ]

    for name in names:
        words = get_word_set(name)

        # Find best cluster key
        matched = False
        for keyword in keyword_priority:
            if keyword in words:
                clusters[keyword].append(name)
                matched = True
                break

        if not matched:
            # Use first significant word as cluster key
            if words:
                first_word = sorted(words, key=lambda w: -len(w))[0]
                clusters[first_word].append(name)
            else:
                unmatched.append(name)

    # Add unmatched to "other" cluster
    if unmatched:
        clusters['other'].extend(unmatched)

    # Merge small clusters if we have too many
    while len(clusters) > max_clusters:
        # Find smallest cluster
        smallest_key = min(clusters.keys(), key=lambda k: len(clusters[k]))
        smallest_items = clusters.pop(smallest_key)

        # Merge into most similar existing cluster
        best_target = None
        best_sim = -1

        for key in clusters.keys():
            sim = word_overlap_ratio(smallest_key, key)
            if sim > best_sim:
                best_sim = sim
                best_target = key

        if best_target:
            clusters[best_target].extend(smallest_items)
        else:
            # Merge into largest cluster
            largest = max(clusters.keys(), key=lambda k: len(clusters[k]))
            clusters[largest].extend(smallest_items)

    return dict(clusters)


def build_hierarchy(entries: List[Dict]) -> Tuple[Dict, Dict]:
    """Build the unified taxonomy hierarchy and mappings."""

    # Group by top level, then collect level 2-5 info
    hierarchy = defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(list)))))
    level_names = defaultdict(lambda: defaultdict(set))

    for entry in entries:
        top = entry['top_level']
        parsed = entry['parsed']
        depth = len(parsed)

        # Extract levels (using original parsed names)
        l2 = parsed[1] if depth > 1 else ""
        l3 = parsed[2] if depth > 2 else ""
        l4 = parsed[3] if depth > 3 else ""
        l5 = parsed[4] if depth > 4 else ""

        if l2:
            level_names[(top, 2)].add(l2)
        if l3:
            level_names[(top, l2, 3)].add(l3)
        if l4:
            level_names[(top, l2, l3, 4)].add(l4)
        if l5:
            level_names[(top, l2, l3, l4, 5)].add(l5)

        # Store in hierarchy
        if l2:
            hierarchy[top][l2][l3][l4][l5].append(entry)

    # Build unified naming structure
    unified = {}
    l2_mappings = {}  # original l2 -> unified l2

    for top in hierarchy.keys():
        l2_names = list(level_names[(top, 2)])

        # Cluster level 2 categories (target 3-20 per top level)
        l2_clusters = cluster_similar_names(l2_names, max_clusters=20)

        unified[top] = {}
        l2_mappings[top] = {}

        for cluster_key, cluster_members in l2_clusters.items():
            # Create unified level 2 name
            unified_l2 = create_unified_name(cluster_members, parent_name=top)

            # Store mapping
            for member in cluster_members:
                l2_mappings[top][member] = unified_l2

            unified[top][unified_l2] = {'members': cluster_members, 'children': {}}

            # Gather all L3 for this cluster
            all_l3 = set()
            for l2_member in cluster_members:
                all_l3.update(level_names.get((top, l2_member, 3), set()))

            if all_l3:
                l3_clusters = cluster_similar_names(list(all_l3), max_clusters=15)

                l3_mappings = {}
                for l3_key, l3_members in l3_clusters.items():
                    unified_l3 = create_unified_name(l3_members, parent_name=unified_l2)

                    for member in l3_members:
                        l3_mappings[member] = unified_l3

                    unified[top][unified_l2]['children'][unified_l3] = {'members': l3_members, 'children': {}}

                    # Gather L4
                    all_l4 = set()
                    for l2_member in cluster_members:
                        for l3_member in l3_members:
                            all_l4.update(level_names.get((top, l2_member, l3_member, 4), set()))

                    if all_l4:
                        l4_clusters = cluster_similar_names(list(all_l4), max_clusters=12)

                        l4_mappings = {}
                        for l4_key, l4_members in l4_clusters.items():
                            unified_l4 = create_unified_name(l4_members, parent_name=unified_l3)

                            for member in l4_members:
                                l4_mappings[member] = unified_l4

                            unified[top][unified_l2]['children'][unified_l3]['children'][unified_l4] = {'members': l4_members, 'children': {}}

                            # Gather L5
                            all_l5 = set()
                            for l2_member in cluster_members:
                                for l3_member in l3_members:
                                    for l4_member in l4_members:
                                        all_l5.update(level_names.get((top, l2_member, l3_member, l4_member, 5), set()))

                            if all_l5:
                                l5_list = [x for x in all_l5 if x]
                                if l5_list:
                                    l5_clusters = cluster_similar_names(l5_list, max_clusters=10)

                                    for l5_key, l5_members in l5_clusters.items():
                                        unified_l5 = create_unified_name(l5_members, parent_name=unified_l4)
                                        unified[top][unified_l2]['children'][unified_l3]['children'][unified_l4]['children'][unified_l5] = {'members': l5_members}

    return unified, l2_mappings


def find_best_match(search_term: str, options: Dict[str, dict]) -> Optional[str]:
    """Find the best matching unified name for a search term."""
    if not options:
        return None

    # First try exact match in members
    for unified_name, info in options.items():
        members = info.get('members', [])
        if search_term in members or search_term.lower() in [m.lower() for m in members]:
            return unified_name

    # Then try fuzzy match
    best_match = None
    best_score = 0

    for unified_name, info in options.items():
        members = info.get('members', [])
        for member in members:
            score = word_overlap_ratio(search_term, member)
            if score > best_score:
                best_score = score
                best_match = unified_name

    if best_score > 0.3:
        return best_match

    # Fallback: return first option
    return list(options.keys())[0] if options else None


def map_entry_to_unified(entry: Dict, unified: Dict) -> Tuple[str, str, str, str, str]:
    """Map a single entry to unified taxonomy levels."""
    top = entry['top_level']
    parsed = entry['parsed']
    depth = len(parsed)

    result = [top, "", "", "", ""]

    if top not in unified:
        return tuple(result)

    l2_options = unified[top]

    # Find level 2
    if depth >= 2:
        l2_search = parsed[1]
        unified_l2 = find_best_match(l2_search, l2_options)
        if unified_l2:
            result[1] = unified_l2

            # Find level 3
            if depth >= 3:
                l3_options = l2_options.get(unified_l2, {}).get('children', {})
                l3_search = parsed[2]
                unified_l3 = find_best_match(l3_search, l3_options)
                if unified_l3:
                    result[2] = unified_l3

                    # Find level 4
                    if depth >= 4:
                        l4_options = l3_options.get(unified_l3, {}).get('children', {})
                        l4_search = parsed[3]
                        unified_l4 = find_best_match(l4_search, l4_options)
                        if unified_l4:
                            result[3] = unified_l4

                            # Find level 5
                            if depth >= 5:
                                l5_options = l4_options.get(unified_l4, {}).get('children', {})
                                l5_search = parsed[4]
                                unified_l5 = find_best_match(l5_search, l5_options)
                                if unified_l5:
                                    result[4] = unified_l5

    return tuple(result)


def generate_outputs(entries: List[Dict], unified: Dict):
    """Generate the two output CSV files."""

    # Output 1: Full taxonomy mapping
    full_output = []
    for entry in entries:
        mapping = map_entry_to_unified(entry, unified)
        full_output.append({
            'source': entry['source'],
            'category_path': entry['original_path'],
            'depth': entry['depth'],
            'unified_level_1': mapping[0],
            'unified_level_2': mapping[1],
            'unified_level_3': mapping[2],
            'unified_level_4': mapping[3],
            'unified_level_5': mapping[4]
        })

    # Write full output
    with open(os.path.join(OUTPUT_DIR, 'unified_taxonomy_full.csv'), 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['source', 'category_path', 'depth',
                                                'unified_level_1', 'unified_level_2',
                                                'unified_level_3', 'unified_level_4', 'unified_level_5'])
        writer.writeheader()
        writer.writerows(full_output)

    print(f"Written {len(full_output)} rows to unified_taxonomy_full.csv")

    # Output 2: Hierarchy structure
    hierarchy_rows = []

    def add_hierarchy_paths(l1, l2_dict):
        for l2, l2_info in l2_dict.items():
            # Add L1-L2 path
            hierarchy_rows.append({
                'unified_level_1': l1,
                'unified_level_2': l2,
                'unified_level_3': '',
                'unified_level_4': '',
                'unified_level_5': ''
            })

            for l3, l3_info in l2_info.get('children', {}).items():
                # Add L1-L2-L3 path
                hierarchy_rows.append({
                    'unified_level_1': l1,
                    'unified_level_2': l2,
                    'unified_level_3': l3,
                    'unified_level_4': '',
                    'unified_level_5': ''
                })

                for l4, l4_info in l3_info.get('children', {}).items():
                    # Add L1-L2-L3-L4 path
                    hierarchy_rows.append({
                        'unified_level_1': l1,
                        'unified_level_2': l2,
                        'unified_level_3': l3,
                        'unified_level_4': l4,
                        'unified_level_5': ''
                    })

                    for l5, l5_info in l4_info.get('children', {}).items():
                        # Add full path
                        hierarchy_rows.append({
                            'unified_level_1': l1,
                            'unified_level_2': l2,
                            'unified_level_3': l3,
                            'unified_level_4': l4,
                            'unified_level_5': l5
                        })

    # Add level 1 entries and descend
    for l1, l2_dict in sorted(unified.items()):
        hierarchy_rows.append({
            'unified_level_1': l1,
            'unified_level_2': '',
            'unified_level_3': '',
            'unified_level_4': '',
            'unified_level_5': ''
        })
        add_hierarchy_paths(l1, l2_dict)

    # Remove duplicates while preserving order
    seen = set()
    unique_rows = []
    for row in hierarchy_rows:
        key = (row['unified_level_1'], row['unified_level_2'], row['unified_level_3'],
               row['unified_level_4'], row['unified_level_5'])
        if key not in seen:
            seen.add(key)
            unique_rows.append(row)

    # Sort by hierarchy levels
    unique_rows.sort(key=lambda x: (x['unified_level_1'], x['unified_level_2'],
                                     x['unified_level_3'], x['unified_level_4'], x['unified_level_5']))

    with open(os.path.join(OUTPUT_DIR, 'unified_taxonomy_hierarchy.csv'), 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['unified_level_1', 'unified_level_2',
                                                'unified_level_3', 'unified_level_4', 'unified_level_5'])
        writer.writeheader()
        writer.writerows(unique_rows)

    print(f"Written {len(unique_rows)} hierarchy paths to unified_taxonomy_hierarchy.csv")

    return full_output, unique_rows


def validate_taxonomy(unified: Dict, full_output: List[Dict]):
    """Validate the taxonomy against the rules."""
    print("\n=== Taxonomy Validation ===")

    # Rule 1: 10-20 top level categories
    num_top = len(unified)
    status1 = "✓" if 10 <= num_top <= 20 else "✗"
    print(f"{status1} Top-level categories: {num_top} (target: 10-20)")

    # Count subcategories per level
    l2_counts = []
    l3_counts = []
    l4_counts = []
    l5_counts = []

    for l1, l2_dict in unified.items():
        l2_count = len(l2_dict)
        l2_counts.append(l2_count)

        for l2, l2_info in l2_dict.items():
            l3_dict = l2_info.get('children', {})
            l3_count = len(l3_dict)
            if l3_count > 0:
                l3_counts.append(l3_count)

            for l3, l3_info in l3_dict.items():
                l4_dict = l3_info.get('children', {})
                l4_count = len(l4_dict)
                if l4_count > 0:
                    l4_counts.append(l4_count)

                for l4, l4_info in l4_dict.items():
                    l5_dict = l4_info.get('children', {})
                    l5_count = len(l5_dict)
                    if l5_count > 0:
                        l5_counts.append(l5_count)

    def format_range(counts):
        if not counts:
            return "N/A"
        return f"min={min(counts)}, max={max(counts)}, avg={sum(counts)/len(counts):.1f}"

    # Check 3-20 rule for subcategories
    l2_ok = all(3 <= c <= 20 for c in l2_counts) if l2_counts else True
    status2 = "✓" if l2_ok else "⚠"
    print(f"{status2} Level 2 per parent: {format_range(l2_counts)} (target: 3-20)")

    l3_ok = all(c <= 20 for c in l3_counts) if l3_counts else True
    status3 = "✓" if l3_ok else "⚠"
    print(f"{status3} Level 3 per parent: {format_range(l3_counts)} (target: 3-20)")

    l4_ok = all(c <= 20 for c in l4_counts) if l4_counts else True
    status4 = "✓" if l4_ok else "⚠"
    print(f"{status4} Level 4 per parent: {format_range(l4_counts)} (target: 3-20)")

    l5_ok = all(c <= 20 for c in l5_counts) if l5_counts else True
    status5 = "✓" if l5_ok else "⚠"
    print(f"{status5} Level 5 per parent: {format_range(l5_counts)} (target: 3-20)")

    # Check source distribution
    print("\nSource distribution per top-level category:")
    source_by_top = defaultdict(lambda: defaultdict(int))
    for row in full_output:
        source_by_top[row['unified_level_1']][row['source']] += 1

    for top in sorted(source_by_top.keys()):
        sources = source_by_top[top]
        total = sum(sources.values())
        pcts = {s: f"{c/total*100:.1f}%" for s, c in sources.items()}
        print(f"  {top}: {pcts}")

    # Check level 2 fill rate
    l2_filled = sum(1 for row in full_output if row['unified_level_2'])
    l2_rate = l2_filled / len(full_output) * 100 if full_output else 0
    print(f"\nLevel 2 fill rate: {l2_rate:.1f}% ({l2_filled}/{len(full_output)})")


def main():
    """Main entry point."""
    print("Loading categories from all sources...")
    categories = load_categories()

    print("\nBuilding unified taxonomy...")
    entries = []
    for source, cat_list in categories.items():
        for original_path, parsed in cat_list:
            top_level = determine_top_level(parsed)
            entries.append({
                'source': source,
                'original_path': original_path,
                'parsed': parsed,
                'depth': len(parsed),
                'top_level': top_level
            })

    print(f"Total entries to process: {len(entries)}")

    print("\nBuilding hierarchy and mappings...")
    unified, l2_mappings = build_hierarchy(entries)

    print("\nGenerating output files...")
    full_output, hierarchy_rows = generate_outputs(entries, unified)

    print("\nValidating taxonomy...")
    validate_taxonomy(unified, full_output)

    print("\nDone!")


if __name__ == "__main__":
    main()

