def determine_top_level(parsed_path: List[str]) -> str:
    """Determine the top-level unified category for a path."""
    # Check first 2 levels for matching keywords
    text_to_check = ' '.join(parsed_path[:2]).lower()

    best_match = None
    best_score = 0

    for category_name, keywords in TOP_LEVEL_CATEGORIES:
        score = 0
        for keyword in keywords:
            if keyword in text_to_check:
                # Longer keyword matches get higher scores
                score += len(keyword.split()) * 2
        if score > best_score:
            best_score = score
            best_match = category_name

    return best_match if best_match else "Other | Miscellaneous"


def create_unified_name(names: List[str], parent_name: str = "", max_words: int = 3) -> str:
    """Create a unified category name from multiple names."""
    if not names:
        return "General"

    # Count word frequencies
    word_freq = Counter()
    for name in names:
        words = get_word_set(name)
        word_freq.update(words)

    # Get parent words to avoid overlap
    parent_words = get_word_set(parent_name) if parent_name else set()

    # Get most common words not in parent
    selected = []
    total_names = len(names)

    for word, count in word_freq.most_common():
        if word not in parent_words and len(word) > 2:
            # Check representativeness (at least 30% of names or common enough)
            coverage = count / total_names
            if coverage >= 0.3 or count >= max(3, total_names * 0.2):
                selected.append(word)
                if len(selected) >= max_words:
                    break

    if not selected:
        # Fallback: use most frequent word from first name
        first_words = get_word_set(names[0])
        if first_words:
            selected = [sorted(first_words, key=lambda w: -len(w))[0]]
        else:
            # Use first name directly
            clean_name = re.sub(r'[^\w\s]', '', names[0])[:20]
            return title_case(clean_name)

    return " | ".join(title_case(w) for w in selected)


def cluster_by_first_word(names: List[str], max_clusters: int = 20) -> Dict[str, List[str]]:
    """Cluster names by their first significant word."""
    if not names:
        return {}

    if len(names) <= max_clusters:
        return {name: [name] for name in names}

    # Group by first significant word
    clusters = defaultdict(list)

    for name in names:
        words = name.lower().split()
        # Skip common prefixes
        prefixes_to_skip = {'products', 'supplies', 'accessories', 'equipment', 'items', 'other'}
        key = None
        for word in words:
            clean_word = re.sub(r'[^\w]', '', word)
            if clean_word and len(clean_word) > 2 and clean_word not in prefixes_to_skip:
                key = clean_word
                break
        if not key:
            key = words[0] if words else "other"
        clusters[key].append(name)

    # Merge small clusters if we have too many
    while len(clusters) > max_clusters:
        # Find smallest cluster
        smallest_key = min(clusters.keys(), key=lambda k: len(clusters[k]))
        smallest_items = clusters.pop(smallest_key)

        # Merge into most similar existing cluster
        best_target = None
        best_sim = -1

        for key in clusters.keys():
            sim = word_overlap_ratio(smallest_key, key)
            if sim > best_sim:
                best_sim = sim
                best_target = key

        if best_target:
            clusters[best_target].extend(smallest_items)
        else:
            # Merge into largest cluster
            largest = max(clusters.keys(), key=lambda k: len(clusters[k]))
            clusters[largest].extend(smallest_items)

    return dict(clusters)


def build_hierarchy(entries: List[Dict]) -> Dict:
    """Build the unified taxonomy hierarchy."""

    # Group entries by their path levels
    path_index = defaultdict(lambda: {'entries': [], 'children': defaultdict(lambda: {'entries': [], 'children': defaultdict(lambda: {'entries': [], 'children': defaultdict(lambda: {'entries': [], 'children': defaultdict(list)})})})})

    for entry in entries:
        top = entry['top_level']
        parsed = entry['parsed']
        depth = len(parsed)

        # Store entry at its depth level
        l2 = parsed[1] if depth > 1 else ""
        l3 = parsed[2] if depth > 2 else ""
        l4 = parsed[3] if depth > 3 else ""
        l5 = parsed[4] if depth > 4 else ""

        if l2:
            path_index[top]['children'][l2]['entries'].append(entry)
            if l3:
                path_index[top]['children'][l2]['children'][l3]['entries'].append(entry)
                if l4:
                    path_index[top]['children'][l2]['children'][l3]['children'][l4]['entries'].append(entry)
                    if l5:
                        path_index[top]['children'][l2]['children'][l3]['children'][l4]['children'][l5].append(entry)

    # Build unified structure with clustered names
    unified = {}

    for top, top_data in path_index.items():
        l2_names = list(top_data['children'].keys())

        # Cluster level 2 names
        l2_clusters = cluster_by_first_word(l2_names, max_clusters=20)

        unified[top] = {}

        for cluster_key, cluster_members in l2_clusters.items():
            # Create unified L2 name
            unified_l2 = create_unified_name(cluster_members, parent_name=top)

            unified[top][unified_l2] = {
                'members': set(cluster_members),
                'children': {}
            }

            # Gather all L3 for this cluster
            all_l3 = {}
            for l2_member in cluster_members:
                for l3, l3_data in top_data['children'].get(l2_member, {}).get('children', {}).items():
                    if l3:
                        if l3 not in all_l3:
                            all_l3[l3] = {'entries': [], 'children': {}}
                        all_l3[l3]['entries'].extend(l3_data['entries'])
                        for l4, l4_data in l3_data.get('children', {}).items():
                            if l4 not in all_l3[l3]['children']:
                                all_l3[l3]['children'][l4] = {'entries': [], 'children': {}}
                            all_l3[l3]['children'][l4]['entries'].extend(l4_data['entries'])
                            for l5, l5_entries in l4_data.get('children', {}).items():
                                if l5 not in all_l3[l3]['children'][l4]['children']:
                                    all_l3[l3]['children'][l4]['children'][l5] = []
                                all_l3[l3]['children'][l4]['children'][l5].extend(l5_entries)

            if all_l3:
                l3_clusters = cluster_by_first_word(list(all_l3.keys()), max_clusters=15)

                for l3_key, l3_members in l3_clusters.items():
                    unified_l3 = create_unified_name(l3_members, parent_name=unified_l2)
                    unified[top][unified_l2]['children'][unified_l3] = {
                        'members': set(l3_members),
                        'children': {}
                    }

                    # Gather L4
                    all_l4 = {}
                    for l3_member in l3_members:
                        for l4, l4_data in all_l3.get(l3_member, {}).get('children', {}).items():
                            if l4:
                                if l4 not in all_l4:
                                    all_l4[l4] = {'entries': [], 'children': {}}
                                all_l4[l4]['entries'].extend(l4_data['entries'])
                                for l5, l5_entries in l4_data.get('children', {}).items():
                                    if l5 not in all_l4[l4]['children']:
                                        all_l4[l4]['children'][l5] = []
                                    all_l4[l4]['children'][l5].extend(l5_entries)

                    if all_l4:
                        l4_clusters = cluster_by_first_word(list(all_l4.keys()), max_clusters=12)

                        for l4_key, l4_members in l4_clusters.items():
                            unified_l4 = create_unified_name(l4_members, parent_name=unified_l3)
                            unified[top][unified_l2]['children'][unified_l3]['children'][unified_l4] = {
                                'members': set(l4_members),
                                'children': {}
                            }

                            # Gather L5
                            all_l5 = set()
                            for l4_member in l4_members:
                                for l5 in all_l4.get(l4_member, {}).get('children', {}).keys():
                                    if l5:
                                        all_l5.add(l5)

                            if all_l5:
                                l5_clusters = cluster_by_first_word(list(all_l5), max_clusters=10)

                                for l5_key, l5_members in l5_clusters.items():
                                    unified_l5 = create_unified_name(l5_members, parent_name=unified_l4)
                                    unified[top][unified_l2]['children'][unified_l3]['children'][unified_l4]['children'][unified_l5] = {
                                        'members': set(l5_members)
                                    }

    return unified


def find_best_match(search_term: str, options: Dict[str, dict]) -> Optional[str]:
    """Find the best matching unified name for a search term."""
    if not options:
        return None

    search_lower = search_term.lower()

    # First try exact match in members
    for unified_name, info in options.items():
        members = info.get('members', set())
        if search_term in members or search_lower in {m.lower() for m in members}:
            return unified_name

    # Then try fuzzy match
    best_match = None
    best_score = 0

    for unified_name, info in options.items():
        members = info.get('members', set())
        for member in members:
            score = word_overlap_ratio(search_term, member)
            if score > best_score:
                best_score = score
                best_match = unified_name

    if best_score > 0.3:
        return best_match

    # Fallback: return first option
    return list(options.keys())[0] if options else None


def map_entry_to_unified(entry: Dict, unified: Dict) -> Tuple[str, str, str, str, str]:
    """Map a single entry to unified taxonomy levels."""
    top = entry['top_level']
    parsed = entry['parsed']
    depth = len(parsed)

    result = [top, "", "", "", ""]

    if top not in unified:
        return tuple(result)

    l2_options = unified[top]

    # Find level 2
    if depth >= 2:
        l2_search = parsed[1]
        unified_l2 = find_best_match(l2_search, l2_options)
        if unified_l2:
            result[1] = unified_l2

            # Find level 3
            if depth >= 3:
                l3_options = l2_options.get(unified_l2, {}).get('children', {})
                l3_search = parsed[2]
                unified_l3 = find_best_match(l3_search, l3_options)
                if unified_l3:
                    result[2] = unified_l3

                    # Find level 4
                    if depth >= 4:
                        l4_options = l3_options.get(unified_l3, {}).get('children', {})
                        l4_search = parsed[3]
                        unified_l4 = find_best_match(l4_search, l4_options)
                        if unified_l4:
                            result[3] = unified_l4

                            # Find level 5
                            if depth >= 5:
                                l5_options = l4_options.get(unified_l4, {}).get('children', {})
                                l5_search = parsed[4]
                                unified_l5 = find_best_match(l5_search, l5_options)
                                if unified_l5:
                                    result[4] = unified_l5

    return tuple(result)


def generate_outputs(entries: List[Dict], unified: Dict):
    """Generate the two output CSV files."""

    # Output 1: Full taxonomy mapping
    full_output = []
    for entry in entries:
        mapping = map_entry_to_unified(entry, unified)
        full_output.append({
            'source': entry['source'],
            'category_path': entry['original_path'],
            'depth': entry['depth'],
            'unified_level_1': mapping[0],
            'unified_level_2': mapping[1],
            'unified_level_3': mapping[2],
            'unified_level_4': mapping[3],
            'unified_level_5': mapping[4]
        })

    # Write full output
    with open(os.path.join(OUTPUT_DIR, 'unified_taxonomy_full.csv'), 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['source', 'category_path', 'depth',
                                                'unified_level_1', 'unified_level_2',
                                                'unified_level_3', 'unified_level_4', 'unified_level_5'])
        writer.writeheader()
        writer.writerows(full_output)

    print(f"Written {len(full_output)} rows to unified_taxonomy_full.csv")

    # Output 2: Hierarchy structure
    hierarchy_rows = []

    def add_hierarchy_paths(l1, l2_dict):
        for l2 in sorted(l2_dict.keys()):
            l2_info = l2_dict[l2]
            # Add L1-L2 path
            hierarchy_rows.append({
                'unified_level_1': l1,
                'unified_level_2': l2,
                'unified_level_3': '',
                'unified_level_4': '',
                'unified_level_5': ''
            })

            for l3 in sorted(l2_info.get('children', {}).keys()):
                l3_info = l2_info['children'][l3]
                # Add L1-L2-L3 path
                hierarchy_rows.append({
                    'unified_level_1': l1,
                    'unified_level_2': l2,
                    'unified_level_3': l3,
                    'unified_level_4': '',
                    'unified_level_5': ''
                })

                for l4 in sorted(l3_info.get('children', {}).keys()):
                    l4_info = l3_info['children'][l4]
                    # Add L1-L2-L3-L4 path
                    hierarchy_rows.append({
                        'unified_level_1': l1,
                        'unified_level_2': l2,
                        'unified_level_3': l3,
                        'unified_level_4': l4,
                        'unified_level_5': ''
                    })

                    for l5 in sorted(l4_info.get('children', {}).keys()):
                        # Add full path
                        hierarchy_rows.append({
                            'unified_level_1': l1,
                            'unified_level_2': l2,
                            'unified_level_3': l3,
                            'unified_level_4': l4,
                            'unified_level_5': l5
                        })

    # Add level 1 entries and descend
    for l1 in sorted(unified.keys()):
        hierarchy_rows.append({
            'unified_level_1': l1,
            'unified_level_2': '',
            'unified_level_3': '',
            'unified_level_4': '',
            'unified_level_5': ''
        })
        add_hierarchy_paths(l1, unified[l1])

    with open(os.path.join(OUTPUT_DIR, 'unified_taxonomy_hierarchy.csv'), 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['unified_level_1', 'unified_level_2',
                                                'unified_level_3', 'unified_level_4', 'unified_level_5'])
        writer.writeheader()
        writer.writerows(hierarchy_rows)

    print(f"Written {len(hierarchy_rows)} hierarchy paths to unified_taxonomy_hierarchy.csv")

    return full_output, hierarchy_rows


def check_sibling_overlap(siblings: List[str]) -> List[Tuple[str, str, float]]:
    """Check word overlap between sibling categories."""
    issues = []
    for i, s1 in enumerate(siblings):
        for s2 in siblings[i+1:]:
            overlap = word_overlap_ratio(s1, s2)
            if overlap > 0.3:
                issues.append((s1, s2, overlap))
    return issues


def validate_taxonomy(unified: Dict, full_output: List[Dict]):
    """Validate the taxonomy against the rules."""
    print("\n=== Taxonomy Validation ===")

    # Rule 1: 10-20 top level categories
    num_top = len(unified)
    status1 = "PASS" if 10 <= num_top <= 20 else "FAIL"
    print(f"[{status1}] Top-level categories: {num_top} (target: 10-20)")

    # Count subcategories per level
    l2_counts = []
    l3_counts = []
    l4_counts = []
    l5_counts = []

    # Check sibling overlaps
    l1_siblings = list(unified.keys())
    l1_overlap_issues = check_sibling_overlap(l1_siblings)

    l2_overlap_issues = []
    l3_overlap_issues = []

    for l1, l2_dict in unified.items():
        l2_count = len(l2_dict)
        l2_counts.append(l2_count)

        l2_siblings = list(l2_dict.keys())
        l2_overlap_issues.extend(check_sibling_overlap(l2_siblings))

        for l2, l2_info in l2_dict.items():
            l3_dict = l2_info.get('children', {})
            l3_count = len(l3_dict)
            if l3_count > 0:
                l3_counts.append(l3_count)

            l3_siblings = list(l3_dict.keys())
            l3_overlap_issues.extend(check_sibling_overlap(l3_siblings))

            for l3, l3_info in l3_dict.items():
                l4_dict = l3_info.get('children', {})
                l4_count = len(l4_dict)
                if l4_count > 0:
                    l4_counts.append(l4_count)

                for l4, l4_info in l4_dict.items():
                    l5_dict = l4_info.get('children', {})
                    l5_count = len(l5_dict)
                    if l5_count > 0:
                        l5_counts.append(l5_count)

    def format_range(counts):
        if not counts:
            return "N/A"
        return f"min={min(counts)}, max={max(counts)}, avg={sum(counts)/len(counts):.1f}"

    # Check 3-20 rule for subcategories
    l2_ok = all(c <= 20 for c in l2_counts) if l2_counts else True
    status2 = "PASS" if l2_ok else "WARN"
    print(f"[{status2}] Level 2 per parent: {format_range(l2_counts)} (target: 3-20)")

    l3_ok = all(c <= 20 for c in l3_counts) if l3_counts else True
    status3 = "PASS" if l3_ok else "WARN"
    print(f"[{status3}] Level 3 per parent: {format_range(l3_counts)} (target: 3-20)")

    l4_ok = all(c <= 20 for c in l4_counts) if l4_counts else True
    status4 = "PASS" if l4_ok else "WARN"
    print(f"[{status4}] Level 4 per parent: {format_range(l4_counts)} (target: 3-20)")

    l5_ok = all(c <= 20 for c in l5_counts) if l5_counts else True
    status5 = "PASS" if l5_ok else "WARN"
    print(f"[{status5}] Level 5 per parent: {format_range(l5_counts)} (target: 3-20)")

    # Report sibling overlap issues
    print(f"\nSibling overlap analysis (threshold 30%):")
    print(f"  Level 1: {len(l1_overlap_issues)} issues")
    print(f"  Level 2: {len(l2_overlap_issues)} issues")
    print(f"  Level 3: {len(l3_overlap_issues)} issues")

    # Check source distribution
    print("\nSource distribution per top-level category:")
    source_by_top = defaultdict(lambda: defaultdict(int))
    for row in full_output:
        source_by_top[row['unified_level_1']][row['source']] += 1

    for top in sorted(source_by_top.keys()):
        sources = source_by_top[top]
        total = sum(sources.values())
        pcts = {s: f"{c/total*100:.1f}%" for s, c in sources.items()}
        print(f"  {top}: {pcts}")

    # Check level 2 fill rate
    l2_filled = sum(1 for row in full_output if row['unified_level_2'])
    l2_rate = l2_filled / len(full_output) * 100 if full_output else 0
    print(f"\nLevel fill rates:")
    print(f"  Level 2: {l2_rate:.1f}% ({l2_filled}/{len(full_output)})")

    l3_filled = sum(1 for row in full_output if row['unified_level_3'])
    l3_rate = l3_filled / len(full_output) * 100 if full_output else 0
    print(f"  Level 3: {l3_rate:.1f}% ({l3_filled}/{len(full_output)})")


def main():
    """Main entry point."""
    print("Loading categories from all sources...")
    categories = load_categories()

    print("\nBuilding unified taxonomy...")
    entries = []
    for source, cat_list in categories.items():
        for original_path, parsed in cat_list:
            top_level = determine_top_level(parsed)
            entries.append({
                'source': source,
                'original_path': original_path,
                'parsed': parsed,
                'depth': len(parsed),
                'top_level': top_level
            })

    print(f"Total entries to process: {len(entries)}")

    print("\nBuilding hierarchy...")
    unified = build_hierarchy(entries)

    print("\nGenerating output files...")
    full_output, hierarchy_rows = generate_outputs(entries, unified)

    print("\nValidating taxonomy...")
    validate_taxonomy(unified, full_output)

    print("\nDone!")


if __name__ == "__main__":
    main()

